WITH curr AS (
  SELECT * FROM bank_dwh.D_CUST WHERE IS_CURR = true
), prev AS (
  SELECT * FROM bank_dwh.D_CUST WHERE IS_CURR = false
)
SELECT COUNT(DISTINCT curr.BUS_ID) AS num_changed
FROM curr
JOIN prev ON curr.BUS_ID = prev.BUS_ID AND prev.VRSN_NBR = curr.VRSN_NBR - 1
WHERE curr.CUST_SGMNT_CD1 <> prev.CUST_SGMNT_CD1;

SELECT COUNT(DISTINCT BUS_ID) AS active_customers
FROM bank_dwh.D_CUST
WHERE IS_ACTV = TRUE AND IS_CURR = TRUE;
